/**
 * iPin ImagesLoaded  v1.0.0
 * Fires a callback once every <img> inside a container has
 * finished loading (or errored out).
 *
 * API surface matches the Desandro imagesLoaded plugin so
 * existing call-sites work without changes:
 *
 *   $(container).imagesLoaded(callback)
 *   $(container).imagesLoaded().done(callback)   // deferred form
 *
 * Written from scratch for iPin Modern.
 * No external dependencies beyond jQuery.
 */
;(function ($) {
  'use strict';

  /**
   * Collect every <img> inside `el`, including those nested
   * inside <picture> elements.
   *
   * @param  {Element} el
   * @returns {HTMLImageElement[]}
   */
  function collectImages(el) {
    var imgs  = [];
    var nodes = el.querySelectorAll('img');
    for (var i = 0; i < nodes.length; i++) {
      imgs.push(nodes[i]);
    }
    return imgs;
  }

  /**
   * Core loader — returns a jQuery Deferred that resolves once
   * every image in `imgs` has settled (load or error).
   *
   * @param  {HTMLImageElement[]} imgs
   * @returns {jQuery.Deferred}
   */
  function waitForImages(imgs) {
    var dfd     = $.Deferred();
    var total   = imgs.length;
    var settled = 0;

    // No images at all — resolve immediately.
    if (total === 0) {
      setTimeout(function () { dfd.resolve(); }, 0);
      return dfd;
    }

    function tick() {
      settled++;
      if (settled === total) {
        dfd.resolve();
      }
    }

    for (var i = 0; i < imgs.length; i++) {
      (function (img) {
        if (img.complete) {
          // Already settled (cached or error) — count on next tick so
          // .done() handlers attached after this call still fire.
          setTimeout(tick, 0);
          return;
        }

        // Load through a proxy Image so we don't touch the DOM element.
        var proxy = new Image();

        if (img.crossOrigin) {
          proxy.crossOrigin = img.crossOrigin;
        }

        proxy.onload  = tick;
        proxy.onerror = tick;  // broken image still counts as done

        // Set src AFTER attaching handlers to avoid sync-fire on cached
        // images in certain browsers.
        proxy.src = img.currentSrc || img.src;

        // Catch the case where the browser already completed the proxy
        // synchronously (very warm cache).
        if (proxy.complete) {
          proxy.onload  = null;
          proxy.onerror = null;
          tick();
        }
      }(imgs[i]));
    }

    return dfd;
  }

  /**
   * jQuery plugin.
   *
   * @param  {Function} [callback]   Called when all images are done.
   * @returns {jQuery|Promise}       `this` if callback given, else Promise.
   */
  $.fn.imagesLoaded = function (callback) {
    var imgs = [];
    var self = this;

    this.each(function () {
      // The element itself might be an <img>.
      if (this.nodeName === 'IMG') {
        imgs.push(this);
      }
      var nested = collectImages(this);
      for (var i = 0; i < nested.length; i++) {
        imgs.push(nested[i]);
      }
    });

    var dfd = waitForImages(imgs);

    if (typeof callback === 'function') {
      dfd.done(function () { callback.call(self[0]); });
      return this;  // chainable
    }

    return dfd.promise();  // deferred usage
  };

}(jQuery));
